package ai.neargo.shop.merchantbridge;
import ai.neargo.shop.common.*;
import ai.neargo.shop.merchant.brand.StoredValueFinancialAuthorityService;
import ai.neargo.shop.payclient.*;
import ai.neargo.shop.spi.storedvalue.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Component;
/** Public clients supply resource identifiers only. Live Core authority is rebuilt on every invocation. */
@Component
public class StoredValueFinanceContext {
 private final ManagementAccess access;private final StoredValueFinancialAuthorityService authority;private final StoredValueIssuerAppService issuers;private final StoredValueFinanceAppService finance;private final ai.neargo.shop.promotion.service.StoredValueActivityReportOwnership activityOwnership;
 public StoredValueFinanceContext(ManagementAccess access,StoredValueFinancialAuthorityService authority,StoredValueIssuerAppService issuers,StoredValueFinanceAppService finance,ai.neargo.shop.promotion.service.StoredValueActivityReportOwnership activityOwnership){this.access=access;this.authority=authority;this.issuers=issuers;this.finance=finance;this.activityOwnership=activityOwnership;}
 public Map<String,Object> prepare(String management,String entity){return authority.prepare(access.actor(),management,entity);}
 public List<StoredValueFinance.Resource> directory(String management,String type){var actor=access.actor();var resources=authority.financeResources(actor,management,type);return finance.directory(new StoredValueFinance.Directory(actor.tenantNo(),actor.actorKey(),management,"FINANCE",resources,authority.financialEntities(actor,management).keySet()));}
 public record ReadableResource(StoredValueFinance.Resource resource,boolean canGenerate){}
 /** View discovery and command authority are distinct. Pay intersects each party set with issuer relationships. */
 public List<ReadableResource> readableDirectory(String management,String type){
  var actor=access.actor();var refs=authority.financeResources(actor,management,type);var permissions=authority.financialEntities(actor,management);
  var readers=permissions.entrySet().stream().filter(e->e.getValue().contains("sv.settlement.read")).map(Map.Entry::getKey).collect(java.util.stream.Collectors.toSet());
  if(readers.isEmpty())return List.of();
  var visible=finance.directory(new StoredValueFinance.Directory(actor.tenantNo(),actor.actorKey(),management,"FINANCE",refs,readers));if(visible.isEmpty())return List.of();
  var generators=permissions.entrySet().stream().filter(e->e.getValue().contains("sv.settlement.generate")).map(Map.Entry::getKey).collect(java.util.stream.Collectors.toSet());
  var generatable=generators.isEmpty()?Set.<String>of():finance.directory(new StoredValueFinance.Directory(actor.tenantNo(),actor.actorKey(),management,"FINANCE",refs,generators)).stream().map(StoredValueFinance.Resource::issuerNo).collect(java.util.stream.Collectors.toSet());
  return visible.stream().map(r->new ReadableResource(r,generatable.contains(r.issuerNo()))).toList();
 }
 public StoredValueSettlements.Authority financial(String management,String issuer){var actor=access.actor();var ref=issuers.locate(actor.tenantNo(),issuer);authority.financialLookup(actor,management,ref);return authority.financial(actor,management,List.of(new StoredValueSettlements.IssuerGrant(issuer,ref.scopeType(),ref.scopeNo())),Set.of());}
 public StoredValueSettlements.Authority bill(String management,String no,String kind){var location=finance.locate(new StoredValueSettlements.Resource(access.actor().tenantNo(),no,kind));return financial(management,location.issuerNo());}
 public StoredValueSettlements.Authority allFinancial(String management,String type,String issuer){if(issuer!=null){var a=financial(management,issuer);if(type!=null&&!type.equals(a.issuers().getFirst().scopeType()))throw BizException.of(ErrorCode.BAD_REQUEST);return a;}var actor=access.actor();var resources=directory(management,type);if(resources.isEmpty())throw BizException.of(ErrorCode.NOT_FOUND);return authority.financial(actor,management,resources.stream().map(r->new StoredValueSettlements.IssuerGrant(r.issuerNo(),r.scopeType(),r.scopeNo())).toList(),Set.of());}
 public StoredValueFinance.Resource reportResource(String management,String issuer){var actor=access.actor();var ref=issuers.locate(actor.tenantNo(),issuer);authority.reportLookup(actor,management,ref,"BRAND".equals(ref.scopeType())?"sv.brand.report":"sv.store.report");return finance.directory(new StoredValueFinance.Directory(actor.tenantNo(),actor.actorKey(),management,"BUSINESS",List.of(ref),Set.of())).stream().filter(r->issuer.equals(r.issuerNo())).findFirst().orElseThrow(()->BizException.of(ErrorCode.NOT_FOUND));}
 public StoredValueReports.Scope report(String management,StoredValueFinance.Resource r,String occurrenceStore){return new StoredValueReports.Scope(access.actor().tenantNo(),access.actor().actorKey(),management,r.issuerNo(),r.scopeType(),r.scopeNo(),r.currency(),null,occurrenceStore);}
 public StoredValueFinance.Resource reportResource(String management,String type,String scope){var actor=access.actor();var ref=new StoredValueIssuers.ScopeRef(type,scope);authority.reportLookup(actor,management,ref,"BRAND".equals(type)?"sv.brand.report":"sv.store.report");return finance.directory(new StoredValueFinance.Directory(actor.tenantNo(),actor.actorKey(),management,"BUSINESS",List.of(ref),Set.of())).stream().findFirst().orElseThrow(()->BizException.of(ErrorCode.NOT_FOUND));}
 public StoredValueReports.Scope activityReport(String management,StoredValueFinance.Resource r,String activity,boolean activityPermission){var actor=access.actor();var auth=authority.reportLookup(actor,management,new StoredValueIssuers.ScopeRef(r.scopeType(),r.scopeNo()),activityPermission?"sv.activity.report":("BRAND".equals(r.scopeType())?"sv.brand.report":"sv.store.report"));activityOwnership.require(actor.tenantNo(),actor.actorKey(),management,r.scopeType(),r.scopeNo(),auth.operatingEntityNo(),r.currency(),activity);return new StoredValueReports.Scope(actor.tenantNo(),actor.actorKey(),management,r.issuerNo(),r.scopeType(),r.scopeNo(),r.currency(),activity,null);}
 public List<StoredValueReports.Scope> localReports(String management){var actor=access.actor();var stores=authority.businessStores(actor,management);return finance.directory(new StoredValueFinance.Directory(actor.tenantNo(),actor.actorKey(),management,"BUSINESS",stores,Set.of())).stream().map(r->report(management,r,null)).toList();}
 public StoredValueFinance.BatchReports localBatch(String management,String currency,LocalDate from,LocalDate to,String cursor,int size){var actor=access.actor();var refs=authority.businessStores(actor,management);var resources=finance.directory(new StoredValueFinance.Directory(actor.tenantNo(),actor.actorKey(),management,"BUSINESS",refs,Set.of())).stream().filter(r->currency.equals(r.currency())).toList();var periods=new TreeMap<String,StoredValueReports.Period>();for(var r:resources)periods.put(r.issuerNo(),period(r,from,to));var scopes=resources.stream().map(r->report(management,r,null)).toList();return new StoredValueFinance.BatchReports(scopes,period("UTC",from,to),cursor,size,periods);}
 public StoredValueFinance.Resource activityResource(String management,String issuer){var actor=access.actor();var ref=issuers.locate(actor.tenantNo(),issuer);authority.reportLookup(actor,management,ref,"sv.activity.report");return finance.directory(new StoredValueFinance.Directory(actor.tenantNo(),actor.actorKey(),management,"BUSINESS",List.of(ref),Set.of())).stream().filter(r->issuer.equals(r.issuerNo())).findFirst().orElseThrow(()->BizException.of(ErrorCode.NOT_FOUND));}
 public StoredValueReports.Period period(StoredValueFinance.Resource resource,LocalDate from,LocalDate to){return period(resource.businessTimeZone(),from,to);}
 public StoredValueReports.Period period(String zone,LocalDate from,LocalDate to){if(from==null||to==null)throw BizException.of(ErrorCode.BAD_REQUEST);try{return new StoredValueReports.Period(from.atStartOfDay(ZoneId.of(zone)).toInstant(),to.atStartOfDay(ZoneId.of(zone)).toInstant());}catch(DateTimeException e){throw BizException.of(ErrorCode.BAD_REQUEST);}}
 public StoredValueReports.Period financialPeriod(String management,String issuer,LocalDate from,LocalDate to){var r=directory(management,null).stream().filter(x->issuer.equals(x.issuerNo())).findFirst().orElseThrow(()->BizException.of(ErrorCode.NOT_FOUND));return period(r,from,to);}
}
